let user=null,csrf='',currentTab='leads',siteContent=null,editing=null,originalId=null,leadFilter={q:'',status:'',assignee:'',due:'',incoming:'',offset:0},viewSerial=0,activeLead=null;
function localToday(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
const followDate=s=>s?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(s+'T12:00:00')):'Не назначен';
function dueState(l,today=localToday()){return ['won','closed'].includes(l.status)?'done':!l.next_contact?'none':l.next_contact<today?'overdue':l.next_contact===today?'today':'upcoming';}
