async function refreshReminders(){if(!user||document.hidden)return;try{const d=await api('/api/admin/reminders?today='+localToday()),count=d.overdue+d.todayCount,badge=$('#reminder-badge');badge.textContent=String(count);badge.hidden=!count;badge.setAttribute('aria-label','Требуют внимания: '+count);}catch{}}
