const date=s=>new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short'}).format(new Date(s));
const photo=key=>window.facadeAdminAssets?.[key]||(!key?'/assets/project-summary.svg':key.startsWith('media/')?'/'+key:'/assets/'+key+'.webp');
function status(message,error=false){$('#admin-status').textContent=message;$('#admin-status').classList.toggle('error',error);}
async function api(url,{method='GET',body,form=false}={}){const headers={};if(method!=='GET')headers['X-CSRF-Token']=csrf;if(body&&!form)headers['Content-Type']='application/json';const r=await fetch(url,{method,headers,body:body?(form?body:JSON.stringify(body)):undefined,credentials:'same-origin'});let data;try{data=await r.json();}catch{throw Error('Сервер недоступен. Попробуйте позже.');}if(!r.ok){if(r.status===401&&url!=='/api/admin/login')showLogin();throw Object.assign(Error(data.error||'Не удалось выполнить действие.'),{data,statusCode:r.status});}return data;}
