function confirmAction(message){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-text').textContent=message;let settled=false;const finish=value=>{if(settled)return;settled=true;d.close();resolve(value);};$('#confirm-yes').onclick=()=>finish(true);$('#confirm-cancel').onclick=()=>finish(false);d.oncancel=()=>finish(false);d.showModal();});}
function empty(title,body){return `<div class="admin-empty"><h2>${e(title)}</h2><p>${e(body)}</p></div>`;}
function filterKey(){return 'facadepro.crm16.filters.'+encodeURIComponent(user||'');}
function loadLeadFilters(){leadFilter={q:'',status:'',assignee:'',due:'',incoming:'',offset:0};try{const saved=JSON.parse(localStorage.getItem(filterKey())||'null');if(!saved||typeof saved!=='object')return;if(Object.hasOwn(statuses,saved.status))leadFilter.status=saved.status;if(typeof saved.assignee==='string'&&saved.assignee.length<=60)leadFilter.assignee=saved.assignee;if(['overdue','today','upcoming','unscheduled'].includes(saved.due))leadFilter.due=saved.due;if(saved.incoming==='1')leadFilter.incoming='1';}catch{}}
