async function allowLeadNavigation(){if(!activeLead?.hasUnsaved())return true;return confirmAction('В карточке есть несохранённые изменения. Закрыть её без сохранения?');}
async function refreshIncomingBadge(){if(!user||document.hidden)return;try{const state=await api('/api/admin/incoming?mine=0&limit=1&offset=0'),badge=$('#incoming-badge');if(!badge)return;badge.textContent=String(state.unread);badge.hidden=!state.unread;badge.setAttribute('aria-label','Новые входящие: '+state.unread);}catch{}}
const inboxKind={addition:'Материалы заказчика',customer_addition:'Материалы заказчика',quote_response:'Ответ по КП'};
const inboxChoice={discuss:'Обсудить условия',reprice:'Нужен пересчёт',proceed:'Готов перейти к договору'};
function incomingMarkup(entry){return `<article class="incoming-card${entry.processed?' incoming-processed':''}" data-incoming-id="${e(entry.id)}"><div class="incoming-card-heading"><button type="button" class="row-link" data-incoming-lead="${e(entry.leadId)}">${e(entry.reference)}</button><span class="status-tag">${entry.processed?'Обработано':'Требует ответа'}</span></div><h3>${e(inboxKind[entry.kind]||'Сообщение заказчика')}${entry.quoteVersion?' · КП '+e(entry.quoteVersion):''}</h3><p class="muted">${date(entry.createdAt)} · ${e(entry.assignee||'Ответственный не назначен')}</p>${entry.choice?'<p class="incoming-choice">'+e(inboxChoice[entry.choice]||entry.choice)+'</p>':''}${entry.comment?'<p class="incoming-comment">'+e(entry.comment)+'</p>':''}${entry.filesCount?'<p class="incoming-files">Вложений: '+e(entry.filesCount)+'</p>':''}${entry.projectLink&&projectHref(entry.projectLink)?'<a class="text-button" href="'+e(projectHref(entry.projectLink))+'" target="_blank" rel="noopener noreferrer">Открыть материалы по ссылке ↗</a>':''}${entry.processedAt?'<p class="muted">Отмечено '+date(entry.processedAt)+'</p>':''}<div class="incoming-actions"><button type="button" class="lead-contact-button" data-incoming-open="${e(entry.leadId)}">Открыть заявку</button><button type="button" class="lead-contact-button" data-incoming-process="${e(entry.id)}" data-incoming-revision="${e(entry.revision)}" data-incoming-processed="${entry.processed?'false':'true'}">${entry.processed?'Вернуть во входящие':'Обработано'}</button></div><p class="inline-status" data-incoming-status role="status" aria-live="polite"></p></article>`;}
function bindIncomingCards(root,reload,{detail=false}={}){root.querySelectorAll('[data-incoming-lead],[data-incoming-open]').forEach(button=>button.onclick=()=>{const id=button.dataset.incomingLead||button.dataset.incomingOpen;if(detail&&activeLead?.id===id){selectLeadPane('materials');return;}void openLead(id,{pane:'communication'}).catch(err=>status(err.message,true));});root.querySelectorAll('[data-incoming-process]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-incoming-id]'),message=card.querySelector('[data-incoming-status]');button.disabled=true;try{await api('/api/admin/incoming/'+button.dataset.incomingProcess,{method:'PUT',body:{revision:Number(button.dataset.incomingRevision),processed:button.dataset.incomingProcessed==='true'}});await reload();void refreshIncomingBadge();}catch(error){message.textContent=error.message;message.classList.add('error');if(error.statusCode===409)message.textContent+=' Обновите входящие перед повторной отметкой.';}finally{if(button.isConnected)button.disabled=false;}});}
async function incoming({mine=false,offset=0}={}){const serial=viewSerial,data=await api('/api/admin/incoming?'+new URLSearchParams({mine:mine?'1':'0',limit:'100',offset:String(offset)}));if(serial!==viewSerial)return;$('#admin-view').innerHTML=`<div class="incoming-toolbar"><label class="check-line"><input id="incoming-mine" type="checkbox" ${mine?'checked':''}><span>Только мои заявки</span></label><button class="lead-contact-button" type="button" id="incoming-refresh">Обновить</button></div><p class="muted incoming-explanation">Новых входящих: <strong id="incoming-unread">${e(data.unread)}</strong>. Отметка «Обработано» относится к вашему рабочему списку. Новое сообщение заказчика появится отдельно.</p><div id="incoming-list">${data.entries.length?data.entries.map(incomingMarkup).join(''):empty('Входящих пока нет','Здесь появятся вопросы, материалы и ответы заказчиков по КП.')}</div><div class="pagination"><span>Всего: ${e(data.total)}</span><div><button type="button" id="incoming-prev" ${offset===0?'disabled':''}>← Назад</button><button type="button" id="incoming-next" ${!data.hasMore?'disabled':''}>Далее →</button></div></div>`;const reload=()=>incoming({mine,offset}).catch(error=>status(error.message,true));$('#incoming-mine').onchange=()=>void incoming({mine:$('#incoming-mine').checked}).catch(error=>status(error.message,true));$('#incoming-refresh').onclick=reload;$('#incoming-prev').onclick=()=>void incoming({mine,offset:Math.max(0,offset-100)}).catch(error=>status(error.message,true));$('#incoming-next').onclick=()=>void incoming({mine,offset:offset+100}).catch(error=>status(error.message,true));bindIncomingCards($('#incoming-list'),reload);void refreshIncomingBadge();}
function dayLeadMarkup(lead){const p=lead.payload||lead;return `<article class="day-lead" data-day-lead="${e(lead.id)}"><div><button type="button" class="row-link" data-lead="${e(lead.id)}">${e(lead.reference)}</button><span class="status-tag status-${e(lead.status)}">${e(statuses[lead.status]||lead.status)}</span></div><h3>${e(p.name||'Заказчик')}</h3><p class="muted">${[p.company,p.city,p.object].filter(Boolean).map(e).join(' · ')}</p><p>${e(lead.next_action||'Следующее действие не задано')}</p><div class="day-contact-actions">${leadContactActions(p)}<button type="button" class="lead-contact-button" data-day-followup="${e(lead.id)}">Следующий шаг</button></div></article>`;}
async function myDay(){const serial=viewSerial,data=await api('/api/admin/day');if(serial!==viewSerial)return;const titles={overdue:'Просроченные контакты',today:'Контакты на сегодня',new:'Новые назначенные заявки',incoming:'Вопросы и материалы заказчиков'};$('#admin-view').innerHTML=`<div class="day-toolbar"><p>Ваши заявки · ${e(followDate(data.today))}<small>Даты контактов: ${e(data.timezone)}</small></p><button type="button" class="lead-contact-button" id="day-refresh">Обновить</button></div><div class="day-summary">${Object.entries(titles).map(([key,label])=>`<a href="#day-${key}" class="day-summary-${key}"><strong data-day-count="${key}">${e(data.counts[key]||0)}</strong><span>${label}</span></a>`).join('')}</div><div class="day-groups">${Object.entries(titles).map(([key,label])=>`<section class="admin-panel day-group" id="day-${key}" data-day-group="${key}"><h2>${label}</h2>${data.groups[key]?.length?data.groups[key].map(key==='incoming'?incomingMarkup:dayLeadMarkup).join(''):'<p class="muted">Здесь пока нет заявок.</p>'}${data.truncated?.[key]?'<p class="muted">Показаны первые '+e(key==='incoming'?data.limits.incoming:data.limits.leads)+' записей. Полный список доступен в соответствующем разделе.</p>':''}</section>`).join('')}</div>`;const reload=()=>myDay().catch(error=>status(error.message,true));$('#day-refresh').onclick=reload;$$('[data-lead]').forEach(button=>button.onclick=()=>void openLead(button.dataset.lead).catch(error=>status(error.message,true)));$$('[data-day-followup]').forEach(button=>button.onclick=()=>void openLead(button.dataset.dayFollowup,{focusFollowup:true}).catch(error=>status(error.message,true)));bindIncomingCards($('#day-incoming'),reload);void refreshIncomingBadge();}
function selectLeadPane(name){const panes=['request','quote','communication','materials','economics'];if(!panes.includes(name))name='request';$$('[data-lead-panel]').forEach(panel=>panel.hidden=panel.dataset.leadPanel!==name);$$('[data-lead-pane]').forEach(button=>{const selected=button.dataset.leadPane===name;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;});}
function mountLeadWorkspace(pane){const root=$('#admin-view'),workspace=document.createElement('div');workspace.className='lead-workspace';const labels={request:'Заявка',quote:'КП',communication:'Общение',materials:'Материалы',economics:'Экономика'};workspace.innerHTML='<div class="lead-pane-tabs" role="tablist" aria-label="Разделы заявки">'+Object.entries(labels).map(([key,label])=>`<button type="button" role="tab" id="lead-pane-${key}" data-lead-pane="${key}" aria-controls="lead-panel-${key}">${label}</button>`).join('')+'</div>'+Object.keys(labels).map(key=>`<div class="lead-pane" data-lead-panel="${key}" id="lead-panel-${key}" role="tabpanel" aria-labelledby="lead-pane-${key}" tabindex="0"></div>`).join('');root.querySelector('.lead-quickbar').after(workspace);workspace.querySelector('.lead-pane-tabs').after(root.querySelector('#lead-save-status'));const into=name=>workspace.querySelector('[data-lead-panel="'+name+'"]');into('request').append(root.querySelector('.detail-grid'));into('quote').append(root.querySelector('.lead-tools-grid'));const materials=document.createElement('section');materials.className='admin-panel lead-materials';materials.innerHTML='<h2>Материалы по объекту</h2><h3>Вложения к заявке</h3>';const detail=root.querySelector('.lead-request-details'),heading=[...detail.querySelectorAll('h3')].find(node=>node.textContent==='Вложения');if(heading){while(heading.nextSibling)materials.append(heading.nextSibling);heading.remove();}materials.append(root.querySelector('#lead-portal-updates'));into('materials').append(materials);const incoming=document.createElement('section');incoming.className='admin-panel lead-incoming';incoming.innerHTML='<div class="incoming-panel-heading"><h2>Входящие от заказчика</h2><button type="button" class="lead-contact-button" id="lead-incoming-refresh">Обновить</button></div><p class="muted">Отмечайте вопросы и материалы после обработки. Новые сообщения остаются во входящих отдельно.</p><div id="lead-incoming-list"></div><p class="inline-status" id="lead-incoming-status" role="status" aria-live="polite"></p>';into('communication').append(incoming,root.querySelector('.lead-history'));into('economics').append(root.querySelector('.lead-commercial'));const costing=window.facadeQuoteTools16?.markupSplit().costing;if(costing)into('economics').insertAdjacentHTML('beforeend',costing);root.querySelector('.lead-business-grid').remove();root.querySelector('.lead-quickbar').insertAdjacentHTML('beforeend','<button type="button" class="lead-contact-button" id="lead-call-result">Результат звонка</button>');root.insertAdjacentHTML('beforeend','<div class="lead-save-bar"><p id="lead-dirty-status" role="status" aria-live="polite">Заявка сохранена</p><button class="button" id="lead-save-sticky" type="button" disabled>Сохранить заявку</button></div>');$$('[data-lead-pane]').forEach(button=>{button.onclick=()=>selectLeadPane(button.dataset.leadPane);button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=$$('[data-lead-pane]'),i=tabs.indexOf(button),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;selectLeadPane(tabs[next].dataset.leadPane);tabs[next].focus();};});$('#lead-save-sticky').onclick=()=>{selectLeadPane('request');$('#lead-edit').requestSubmit();};selectLeadPane(pane);}
function formSnapshot(form){return JSON.stringify([...form.querySelectorAll('input,textarea,select')].filter(input=>input.name||input.dataset.itemField||input.dataset.costing16Field).map(input=>[input.name||input.dataset.itemField||input.dataset.costing16Field,input.type==='file'?[...input.files].map(file=>[file.name,file.size,file.lastModified]):input.type==='checkbox'||input.type==='radio'?input.checked:input.value]));}
function initLeadDirty(ctx){const savedForms=new Map();ctx.captureForms=()=>{for(const form of $$('#admin-view form'))if(!savedForms.has(form))savedForms.set(form,formSnapshot(form));ctx.refreshDirty();};ctx.markSaved=form=>{if(form)savedForms.set(form,formSnapshot(form));ctx.refreshDirty();};ctx.managementDirty=()=>['note','assignee','next_contact','next_action','status'].some(key=>String($('#lead-edit').elements[key].value)!==String(ctx.l[key]??''));ctx.hasUnsaved=()=>ctx.managementDirty()||[...savedForms].some(([form,saved])=>form.id!=='lead-edit'&&form.isConnected&&formSnapshot(form)!==saved);ctx.refreshDirty=()=>{if(!ctx.current())return;const form=$('#lead-edit'),management=ctx.managementDirty();$('#lead-save-sticky').disabled=!management||form.querySelector('button[type=submit]').disabled;$('#lead-dirty-status').textContent=management?'Есть изменения в заявке':ctx.hasUnsaved()?'Есть несохранённые поля в разделах':'Заявка сохранена';$('#lead-dirty-status').classList.toggle('is-dirty',ctx.hasUnsaved());};const listeners=new AbortController();ctx.dispose=()=>listeners.abort();activeLead=ctx;ctx.captureForms();$('#admin-view').addEventListener('input',()=>ctx.refreshDirty(),{signal:listeners.signal});$('#admin-view').addEventListener('change',()=>ctx.refreshDirty(),{signal:listeners.signal});}
async function bindLeadIncoming(ctx){const root=$('#lead-incoming-list'),reload=async()=>{const data=await api('/api/admin/incoming?'+new URLSearchParams({leadId:ctx.id,mine:'0',limit:'100',offset:'0'}));if(!ctx.current())return;root.innerHTML=data.entries.length?data.entries.map(incomingMarkup).join(''):'<p class="muted">Заказчик пока не прислал новых сообщений.</p>';bindIncomingCards(root,reload,{detail:true});};ctx.refreshIncoming=reload;$('#lead-incoming-refresh').onclick=()=>reload().catch(error=>toolMessage('#lead-incoming-status',error.message,true));try{await reload();}catch(error){if(ctx.current())toolMessage('#lead-incoming-status',error.message,true);}}
async function openCallResult(ctx){if(!ctx.current())return;const dialog=$('#call-result-dialog'),form=$('#call-result-form'),edit=$('#lead-edit');form.reset();form.elements.next_contact.value=edit.elements.next_contact.value;form.elements.next_action.value=edit.elements.next_action.value;toolMessage('#call-result-status','');let key=crypto.randomUUID(),busy=false;const baseline={revision:ctx.l.revision,...Object.fromEntries(['note','assignee','status','next_contact','next_action'].map(field=>[field,ctx.l[field]??'']))};$('#close-call-result').onclick=()=>{if(!busy)dialog.close();};dialog.oncancel=event=>{if(busy)event.preventDefault();};form.oninput=()=>{if(!busy)key=crypto.randomUUID();};form.onsubmit=async event=>{event.preventDefault();if(busy||!ctx.current())return;const body={revision:baseline.revision,idempotency:key,outcome:form.elements.outcome.value,comment:form.elements.comment.value,next_contact:form.elements.next_contact.value,next_action:form.elements.next_action.value};busy=true;[...form.elements].forEach(control=>control.disabled=true);$('#close-call-result').disabled=true;toolMessage('#call-result-status','Сохраняем результат…');try{const result=await api('/api/admin/leads/'+ctx.id+'/call-result',{method:'POST',body}),fresh=await api('/api/admin/leads/'+ctx.id);if(!ctx.current())return;const otherFieldsMatch=['note','assignee','status'].every(field=>String(fresh[field]??'')===String(baseline[field]??'')),followupMatches=['next_contact','next_action'].every(field=>String(fresh[field]??'')===String(result[field]??''));if(otherFieldsMatch&&followupMatches&&(!result.duplicate||['next_contact','next_action'].every(field=>String(result[field]??'')===String(result.entry[field]??'')))){for(const field of ['next_contact','next_action']){if(String(edit.elements[field].value)===String(baseline[field])||String(edit.elements[field].value)===String(body[field]))edit.elements[field].value=fresh[field]||'';ctx.l[field]=fresh[field]||'';}ctx.l.revision=fresh.revision;ctx.refreshDirty();toolMessage('#lead-save-status','Результат звонка и следующий контакт сохранены.');}else{toolMessage('#lead-save-status','Данные заявки изменились у другого сотрудника. Результат звонка сохранён, несохранённые поля оставлены в карточке. Перед сохранением откройте актуальную заявку.',true);}dialog.close();await ctx.refreshHistory?.();void refreshReminders();}catch(error){if(ctx.current())toolMessage('#call-result-status',error.message,true);}finally{busy=false;if(ctx.current()){[...form.elements].forEach(control=>control.disabled=false);$('#close-call-result').disabled=false;}}};dialog.showModal();}
