async function bindPortalTools(ctx){const base='/api/admin/leads/'+ctx.id+'/portal',form=$('#lead-portal-message');let portal=null,busy=false;
 const render=(state,resetMessage=false)=>{if(!ctx.current())return;portal=state;ctx.portal=state;const active=Boolean(state.active),expired=state.expiresAt&&Date.parse(state.expiresAt)<=Date.now();$('#lead-portal-state').textContent=active&&!expired?'Доступ включён'+(state.expiresAt?' · до '+date(state.expiresAt):''):expired?'Срок ссылки истёк':'Доступ не включён';$('#lead-portal-state').classList.toggle('portal-active',active&&!expired);if(resetMessage){form.elements.customerMessage.value=state.customerMessage||'';ctx.markSaved(form);}form.querySelector('button').disabled=false;$('#lead-portal-issue').disabled=false;$('#lead-portal-issue').textContent=active?'Создать новую ссылку':'Создать ссылку для заказчика';$('#lead-portal-revoke').hidden=!active;$('#lead-portal-revoke').disabled=false;$('#lead-portal-note').textContent=active?'Новая ссылка заменит ранее выданную. Передайте её только заказчику.':'Создайте ссылку и передайте её заказчику для продолжения обращения.';const publication=state.quotePublication;$('#lead-portal-quote-state').textContent=publication?(publication.archived?'Версия '+publication.version+' в архиве. Заказчик её не видит.':active&&!expired?'Заказчику видна версия '+publication.version+' · опубликовано '+date(publication.publishedAt):'Версия '+publication.version+' выбрана, доступ по ссылке отключён.'):'Коммерческое предложение ещё не опубликовано.';$('#lead-portal-quote-views').textContent=publication?.firstViewedAt?'PDF открыт '+publication.viewCount+' раз · впервые '+date(publication.firstViewedAt)+(publication.lastViewedAt!==publication.firstViewedAt?' · последний раз '+date(publication.lastViewedAt):''):publication?'PDF ещё не открывали.':'';$('#lead-portal-quote-withdraw').hidden=!publication;$('#lead-portal-quote-refresh').hidden=!publication;ctx.quotePublicationChanged?.();$('#lead-portal-updates').innerHTML=state.updates?.length?'<h3>Дополнения заказчика</h3>'+state.updates.map(update=>`<article class="portal-update"><small>${date(update.createdAt)}</small>${update.comment?'<p>'+e(update.comment)+'</p>':''}${projectHref(update.projectLink)?`<p><a href="${e(projectHref(update.projectLink))}" target="_blank" rel="noopener noreferrer">Открыть ссылку на проект</a></p>`:''}${update.files?.length?'<ul class="attachment-list">'+update.files.map(f=>`<li><a href="/api/admin/files/${e(f.id)}" download>${e(f.name)}</a><small>${(f.size/1024/1024).toFixed(2)} МБ</small></li>`).join('')+'</ul>':''}</article>`).join(''):'';};
 const setBusy=value=>{busy=value;[...form.elements].forEach(control=>control.disabled=value);$('#lead-portal-issue').disabled=value;$('#lead-portal-revoke').disabled=value;$('#lead-portal-quote-withdraw').disabled=value;};
 const mutate=async(action,extras={})=>{if(busy||!portal)return;setBusy(true);try{const r=await api(base,{method:'POST',body:{action,...extras,revision:portal.revision,...(['message','issue'].includes(action)?{customerMessage:form.elements.customerMessage.value}:{})}});if(!ctx.current())return;await ctx.sync(r,{expectedStatus:action==='publishQuote'&&!['won','closed'].includes(ctx.l.status)?'sent':undefined});render(r,['message','issue'].includes(action));if(action==='issue'){const url=new URL(r.url,location.origin);if(url.origin!==location.origin||url.pathname!=='/followup.html'||!/^#[a-f0-9]{64}$/i.test(url.hash))throw Error('Сервер вернул некорректную ссылку. Обновите карточку заявки.');$('#lead-portal-link').value=url.href;$('#lead-portal-link-result').hidden=false;toolMessage('#lead-portal-status','Ссылка создана. Скопируйте и передайте её заказчику.');}else{if(action==='revoke'){$('#lead-portal-link').value='';$('#lead-portal-link-result').hidden=true;}toolMessage('#lead-portal-status',action==='message'?'Сообщение для заказчика сохранено.':action==='publishQuote'?'КП доступно на странице заказчика.':action==='withdrawQuote'?'КП убрано со страницы заказчика.':'Доступ по ссылке отключён.');}}catch(err){if(ctx.current())toolMessage('#lead-portal-status',err.message,true);}finally{if(ctx.current())setBusy(false);}};
 ctx.publishQuote=async quoteId=>{if(!portal?.active||portal.expiresAt&&Date.parse(portal.expiresAt)<=Date.now()){toolMessage('#lead-quote-status','Сначала создайте активную личную ссылку в разделе «Продолжение заявки».',true);return;}await mutate('publishQuote',{quoteId});};ctx.refreshPortal=async()=>{const state=await api(base);if(ctx.current())render(state);};$('#lead-portal-quote-refresh').onclick=()=>ctx.refreshPortal().catch(err=>toolMessage('#lead-portal-status',err.message,true));$('#lead-portal-quote-withdraw').onclick=()=>void mutate('withdrawQuote');form.onsubmit=event=>{event.preventDefault();void mutate('message');};$('#lead-portal-issue').onclick=async()=>{if(busy||!portal)return;if(portal.active&&!await confirmAction('Создать новую личную ссылку? Ранее выданная ссылка перестанет открывать заявку.'))return;await mutate('issue');};$('#lead-portal-revoke').onclick=async()=>{if(busy||!portal)return;if(!await confirmAction('Отключить доступ заказчика по личной ссылке? Вложения и сама заявка сохранятся.'))return;await mutate('revoke');};
 $('#lead-portal-copy').onclick=async()=>{const input=$('#lead-portal-link');try{await navigator.clipboard.writeText(input.value);if(ctx.current())toolMessage('#lead-portal-status','Личная ссылка скопирована.');}catch{input.focus();input.select();toolMessage('#lead-portal-status','Ссылка выделена. Скопируйте её через меню или Ctrl/Cmd+C.');}};
 try{render(await api(base),true);}catch(err){if(ctx.current()){toolMessage('#lead-portal-status',err.message,true);$('#lead-portal-state').textContent='Не удалось проверить доступ. Откройте карточку повторно.';}}
}
async function statistics(days=30){const serial=viewSerial,d=await api('/api/admin/stats?days='+days);if(serial!==viewSerial)return;const titles={page_view:'Посетили сайт',request_start:'Начали заявку',step_2:'Дошли до параметров',step_3:'Дошли до контактов',submitted:'Отправили заявку'};const table=(headers,rows)=>rows.length?'<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+e(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+e(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p class="muted">Данных за выбранный период пока нет.</p>';
 $('#admin-view').innerHTML=`<div class="stats-toolbar"><label>Период<select id="stats-days"><option value="7" ${days===7?'selected':''}>7 дней</option><option value="30" ${days===30?'selected':''}>30 дней</option><option value="90" ${days===90?'selected':''}>90 дней</option></select></label><p>Просмотры и этапы учитываются только у посетителей, разрешивших статистику. Общий счётчик заявок включает все обращения.</p></div><div class="metric-grid"><div><strong>${d.totalLeads}</strong><span>всего заявок</span></div><div><strong>${d.sessions}</strong><span>посещений со статистикой</span></div><div><strong>${d.funnel.find(x=>x.event==='request_start').count}</strong><span>посещений с начатой заявкой</span></div></div><div class="stats-grid"><section class="admin-panel"><h2>Этапы обращения</h2>${d.funnel.map(r=>`<div class="funnel-row"><div><span>${titles[r.event]}</span><strong>${r.count}</strong></div><meter min="0" max="${Math.max(1,...d.funnel.map(x=>x.count))}" value="${r.count}" aria-label="${titles[r.event]}">${r.count}</meter></div>`).join('')}<p class="muted">Один посетитель может начать несколько форм. Разница между этапами показывает, где стоит проверить удобство заполнения.</p></section><section class="admin-panel"><h2>Интерес к услугам</h2>${table(['Направление','Посещения'],d.services.map(r=>[names[r.service]||r.service,r.visitors]))}</section></div><div class="stats-grid"><section class="admin-panel"><h2>Популярные страницы</h2>${table(['Страница','Просмотры','Посещения'],d.pages.map(r=>[r.page,r.views,r.visitors]))}</section><section class="admin-panel"><h2>Какие страницы приводят заявки</h2>${table(['Предшествующая страница','Заявки'],(d.leadPages||[]).map(r=>[r.page,r.count]))}</section></div><div class="stats-grid"><section class="admin-panel"><h2>Источники переходов</h2>${table(['Источник','Посещения'],d.sources.map(r=>[r.source==='direct'?'Прямой / внутренний':r.source,r.visitors]))}</section><section class="admin-panel"><h2>Заявки по дням</h2>${table(['Дата','Количество'],d.leadsByDay.map(r=>[r.day,r.count]))}</section></div>`;
 $('#stats-days').onchange=event=>statistics(Number(event.target.value)).catch(err=>status(err.message,true));}
async function projects(){const serial=viewSerial;siteContent=await api('/api/admin/content');if(serial!==viewSerial)return;$('#admin-view').innerHTML=`<div class="project-toolbar"><p>${siteContent.projects.length} проектов · изменения появляются на сайте после сохранения.</p><button type="button" class="button" id="add-project">Добавить проект +</button></div><div class="admin-project-grid">${siteContent.projects.map(p=>`<article class="admin-project-card"><img src="${photo(p.images[0])}" alt="${e(p.title)}"><div><span class="status-tag">${p.published?'Опубликован':'Скрыт'}</span><h2>${e(p.title)}</h2><p>${e(p.location)}</p><button type="button" class="text-button" data-project-edit="${p.id}">Редактировать ↗</button></div></article>`).join('')}</div>`;$('#add-project').onclick=()=>editProject(null);$$('[data-project-edit]').forEach(b=>b.onclick=()=>editProject(b.dataset.projectEdit));}
function editProject(id){originalId=id;editing=structuredClone(id?siteContent.projects.find(p=>p.id===id):{id:'',title:'',type:'Жилые комплексы',location:'',period:'',volume:'',client:'',work:'',images:[],case:{},serviceIds:[],geo:null,published:false});const form=$('#project-form');form.reset();for(const key of ['id','title','type','location','period','volume','client','work'])form.elements.namedItem(key).value=editing[key]||'';for(const key of ['task','challenge','solution','result'])form.elements.namedItem(key).value=editing.case?.[key]||'';form.elements.published.checked=editing.published;$$('input[name=projectService]').forEach(x=>x.checked=(editing.serviceIds||[]).includes(x.value));form.elements.map_label.value=editing.geo?.label||'';form.elements.map_lat.value=editing.geo?.lat??'';form.elements.map_lng.value=editing.geo?.lng??'';form.elements.map_precision.value=editing.geo?.precision||'city';form.elements.id.readOnly=Boolean(id);$('#project-editor-title').textContent=id?'Редактировать проект':'Новый проект';$('#remove-project').hidden=!id;$('#project-error').textContent='';renderPhotos();window.facadeAdmin6?.project();$('#project-dialog').showModal();$('#project-dialog').scrollTop=0;}
function renderPhotos(){const root=$('#editor-photos');root.innerHTML=editing.images.map((key,i)=>`<div class="editor-photo"><img src="${photo(key)}" alt="Фото ${i+1}"><div><button type="button" data-up="${i}" aria-label="Переместить фото ${i+1} раньше" ${i===0?'disabled':''}>←</button><span>${i===0?'Обложка':i+1}</span><button type="button" data-down="${i}" aria-label="Переместить фото ${i+1} позже" ${i===editing.images.length-1?'disabled':''}>→</button><button type="button" data-remove-image="${i}" aria-label="Удалить фото ${i+1}">×</button></div></div>`).join('');root.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up);[editing.images[i],editing.images[i-1]]=[editing.images[i-1],editing.images[i]];renderPhotos();});root.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.down);[editing.images[i],editing.images[i+1]]=[editing.images[i+1],editing.images[i]];renderPhotos();});root.querySelectorAll('[data-remove-image]').forEach(b=>b.onclick=()=>{editing.images.splice(Number(b.dataset.removeImage),1);renderPhotos();window.facadeAdmin6?.photos();});}
$('#project-image').onchange=async event=>{const file=event.target.files[0];if(!file)return;$('#project-error').textContent='';if(editing.images.length>=12||file.size>10*1024*1024){$('#project-error').textContent='До 12 фотографий, каждая до 10 МБ.';return;}const form=new FormData();form.append('files',file);$('#save-project').disabled=true;$('#project-error').textContent='Загружаем фотографию…';try{const r=await api('/api/admin/media',{method:'POST',body:form,form:true});editing.images.push(r.key);renderPhotos();window.facadeAdmin6?.photos();$('#project-error').textContent='Фотография добавлена. Сохраните проект.';}catch(err){$('#project-error').textContent=err.message;}finally{$('#save-project').disabled=false;event.target.value='';}};
function collectProject(){if(!editing.images.length&&siteContent.workflow?.some(r=>r.project===editing.id))throw Error('Сначала замените фотографию проекта в разделе этапов работы.');const f=new FormData($('#project-form'));for(const key of ['id','title','type','location','period','volume','client','work'])editing[key]=f.get(key);editing.case={};for(const key of ['task','challenge','solution','result'])editing.case[key]=f.get(key);editing.published=f.get('published')==='on';editing.serviceIds=f.getAll('projectService');const lat=f.get('map_lat'),lng=f.get('map_lng'),label=f.get('map_label').trim();if((lat||lng||label)&&(!lat||!lng||!label)){throw Error('Заполните название отметки и обе координаты или оставьте все три поля пустыми.');}editing.geo=lat&&lng&&label?{lat:Number(lat),lng:Number(lng),label,precision:f.get('map_precision')}:null;const next=structuredClone(siteContent);if(originalId)next.projects[next.projects.findIndex(p=>p.id===originalId)]=editing;else next.projects.push(editing);next.materials=(next.materials||[]).map(r=>r.project===editing.id&&r.poster&&!editing.images.includes(r.poster)?{...r,poster:editing.images[0]}:r);next.workflow=(next.workflow||[]).map(r=>r.project===editing.id&&!editing.images.includes(r.image)?{...r,image:editing.images[0]}:r);return next;}
$('#project-form').onsubmit=async event=>{event.preventDefault();if(window.facadeAdmin6?.uploading())return;let next;try{next=collectProject();}catch(err){$('#project-error').textContent=err.message;return;}$('#save-project').disabled=true;$('#project-error').textContent='Сохраняем страницы сайта…';try{siteContent=await api('/api/admin/content',{method:'PUT',body:next});$('#project-dialog').close();await projects();status('Проект сохранён. Страницы сайта обновлены.');}catch(err){$('#project-error').textContent=err.message;}finally{$('#save-project').disabled=false;}};
$('#remove-project').onclick=async()=>{if(!await confirmAction('Удалить проект «'+editing.title+'» с сайта? Фотографии остальных проектов останутся.'))return;const next=structuredClone(siteContent);next.projects=next.projects.filter(p=>p.id!==originalId);next.materials=(next.materials||[]).filter(r=>r.project!==originalId);next.workflow=(next.workflow||[]).filter(r=>r.project!==originalId);try{siteContent=await api('/api/admin/content',{method:'PUT',body:next});$('#project-dialog').close();await projects();status('Проект удалён с сайта.');}catch(err){$('#project-error').textContent=err.message;}};
$('#close-project').onclick=()=>$('#project-dialog').close();
